ARCH = '<!-- =====================================================================\n     CAMPIONE 2 · DOSSIER · ARCHITETTURA TECNICA\n     Quattro livelli, letti dall’alto in basso: sorgenti, acquisizione,\n     deployment, utilizzo. Il livello 04 dichiara anche chi lo usa.\n     Grammatica delle linee:\n       CONNETTORE  linea ortogonale, parte dal bordo di un box, arriva al\n                   bordo di un box preciso, ha una freccia.\n       CONFINE     il riquadro dell’ambiente di deployment.\n     Ogni sorgente OT ha il proprio percorso: non e\' disegnato alcun bus\n     comune, perche\' la sua esistenza non e\' confermata.\n     L’integrazione con il gestionale entra a livello di applicazione, non\n     a livello di connettori, ed e\' dichiarata da confermare.\n     Tratteggio riservato al flusso opzionale, dichiarato in legenda.\n     ===================================================================== -->\n<div class="slide lt" id="d03_architettura" data-kind="dossier">\n  <div class="hd"><b>Architettura tecnica</b><span class="pg">03 / 19</span></div>\n  <div class="tt tt--sm">Dalla linea alle persone che decidono, in quattro livelli.</div>\n\n  <svg class="body" width="1152" height="470" viewBox="0 0 1152 470" style="top:180px"\n       role="img" aria-labelledby="a3t a3d">\n    <title id="a3t">Architettura tecnica in quattro livelli</title>\n    <desc id="a3d">Ogni sorgente di linea raggiunge con un percorso proprio il livello di\n      acquisizione, in sola lettura. Dall’acquisizione un flusso unico entra nell’ambiente di\n      deployment e arriva all’applicazione, che scambia dati con il database. Dall’applicazione\n      i dati raggiungono dashboard, report ed export, usati da operatori, operations, energy\n      manager e direzione. Il gestionale è un’integrazione opzionale a livello di applicazione,\n      con innesto da confermare.</desc>\n\n    <!-- etichette di livello, colonna sinistra -->\n    <g font-family="Geist" font-size="14" font-weight="500" fill="rgba(10,10,10,.56)">\n      <text x="0" y="40">01 · Sorgenti</text>\n      <text x="0" y="172">02 · Acquisizione</text>\n      <text x="0" y="300">03 · Deployment</text>\n      <text x="0" y="414">04 · Utilizzo</text>\n    </g>\n    <g font-family="Geist" font-size="13" fill="rgba(10,10,10,.56)">\n      <text x="0" y="436">Operatori, Operations,</text>\n      <text x="0" y="454">Energy Manager, Direzione</text>\n    </g>\n\n    <!-- ---------- 01 sorgenti ---------- -->\n    <g fill="none" stroke="#0A0A0A" stroke-width="1.5">\n      <rect x="150" y="18" width="196" height="46"/>\n      <rect x="370" y="18" width="196" height="46"/>\n      <rect x="590" y="18" width="240" height="46"/>\n    </g>\n    <g font-family="Geist" font-size="16" fill="#0A0A0A" text-anchor="middle">\n      <text x="248" y="47">PLC e dispositivi</text>\n      <text x="468" y="47">Sensori di conta</text>\n      <text x="710" y="47">Contatori energia e utility</text>\n    </g>\n\n    <!-- CONNETTORI: ogni sorgente ha il proprio percorso verso l’acquisizione -->\n    <g fill="none" stroke="#0A0A0A" stroke-width="1.5">\n      <path d="M248 64 L248 96 L408 96 L408 134"/>\n      <path d="M468 64 L468 134"/>\n      <path d="M710 64 L710 112 L528 112 L528 134"/>\n    </g>\n    <g fill="#0A0A0A">\n      <polygon points="408,140 402,130 414,130"/>\n      <polygon points="468,140 462,130 474,130"/>\n      <polygon points="528,140 522,130 534,130"/>\n    </g>\n    <g font-family="Geist" font-size="14" fill="rgba(10,10,10,.56)">\n      <text x="730" y="104">flussi dati di linea</text>\n      <text x="730" y="124">lettura, senza scrittura verso le macchine</text>\n    </g>\n\n    <!-- ---------- 02 acquisizione ---------- -->\n    <rect x="348" y="140" width="240" height="56" fill="none" stroke="#0A0A0A" stroke-width="1.5"/>\n    <g font-family="Geist" font-size="16" fill="#0A0A0A" text-anchor="middle">\n      <text x="468" y="166">Connettori e mappatura</text>\n      <text x="468" y="186">dei segnali</text>\n    </g>\n\n    <!-- CONNETTORE: acquisizione verso l’applicazione, dentro l’ambiente -->\n    <path d="M468 196 L468 214 L680 214 L680 262" fill="none" stroke="#0A0A0A" stroke-width="1.5"/>\n    <polygon points="680,268 674,258 686,258" fill="#0A0A0A"/>\n\n    <!-- ---------- 03 deployment · CONFINE dell’ambiente ---------- -->\n    <rect x="150" y="230" width="700" height="132" fill="none" stroke="#0A0A0A" stroke-width="1.5"/>\n    <text x="166" y="254" font-family="Geist" font-size="14" fill="rgba(10,10,10,.56)">Ambiente di deployment</text>\n    <rect x="174" y="268" width="292" height="72" fill="none" stroke="#0A0A0A" stroke-width="1.5"/>\n    <text x="320" y="311" font-family="Geist" font-size="17" fill="#0A0A0A" text-anchor="middle">Database</text>\n    <rect x="534" y="268" width="292" height="72" fill="#0A0A0A"/>\n    <text x="680" y="311" font-family="Geist" font-size="17" fill="#fff" text-anchor="middle">Applicazione</text>\n    <!-- CONNETTORE bidirezionale fra applicazione e database -->\n    <path d="M472 304 L528 304" stroke="#0A0A0A" stroke-width="1.5"/>\n    <polygon points="466,304 476,298 476,310" fill="#0A0A0A"/>\n    <polygon points="534,304 524,298 524,310" fill="#0A0A0A"/>\n\n    <!-- ---------- integrazione con il gestionale ---------- -->\n    <rect x="912" y="268" width="240" height="72" fill="none" stroke="rgba(10,10,10,.56)" stroke-width="1.5"/>\n    <text x="1032" y="311" font-family="Geist" font-size="16" fill="rgba(10,10,10,.74)"\n          text-anchor="middle">Gestionale ERP</text>\n    <path d="M912 304 L832 304" fill="none" stroke="rgba(10,10,10,.56)" stroke-width="1.5"\n          stroke-dasharray="5 4"/>\n    <polygon points="826,304 836,298 836,310" fill="rgba(10,10,10,.56)"/>\n    <g font-family="Geist" font-size="14" fill="rgba(10,10,10,.56)">\n      <text x="912" y="366">integrazione con il gestionale,</text>\n      <text x="912" y="384">innesto da confermare</text>\n    </g>\n\n    <!-- CONNETTORI: dall’applicazione ai tre utilizzi -->\n    <g fill="none" stroke="#0A0A0A" stroke-width="1.5">\n      <path d="M680 340 L680 380"/>\n      <path d="M320 380 L780 380"/>\n      <path d="M320 380 L320 398"/><path d="M550 380 L550 398"/><path d="M780 380 L780 398"/>\n    </g>\n    <g fill="#0A0A0A">\n      <polygon points="320,404 314,394 326,394"/><polygon points="550,404 544,394 556,394"/>\n      <polygon points="780,404 774,394 786,394"/>\n    </g>\n\n    <!-- ---------- 04 utilizzo ---------- -->\n    <g fill="none" stroke="#0A0A0A" stroke-width="1.5">\n      <rect x="222" y="404" width="196" height="42"/>\n      <rect x="452" y="404" width="196" height="42"/>\n      <rect x="682" y="404" width="196" height="42"/>\n    </g>\n    <g font-family="Geist" font-size="16" fill="#0A0A0A" text-anchor="middle">\n      <text x="320" y="431">Dashboard</text><text x="550" y="431">Report</text>\n      <text x="780" y="431">Export</text>\n    </g>\n\n    <!-- legenda del tratteggio -->\n    <g transform="translate(912,408)">\n      <path d="M0 8 L34 8" stroke="#0A0A0A" stroke-width="1.5"/>\n      <text x="44" y="13" font-family="Geist" font-size="14" fill="rgba(10,10,10,.74)">flusso previsto</text>\n      <path d="M0 34 L34 34" stroke="rgba(10,10,10,.56)" stroke-width="1.5" stroke-dasharray="5 4"/>\n      <text x="44" y="39" font-family="Geist" font-size="14" fill="rgba(10,10,10,.74)">flusso opzionale</text>\n    </g>\n  </svg>\n\n  <div class="ft"><span class="wm">D<i>.</i>Factory</span>\n    <span>Compatibilità di protocolli e dispositivi verificata in audit</span></div>\n</div>\n\n'
REFYN = '<!-- =====================================================================\n     CAMPIONE 3 · DOSSIER · REFYN\n     Visual: ciclo operativo. Tre stati con lo stesso trattamento, due\n     connettori in avanti e un connettore di ritorno che chiude il ciclo.\n     L’enfasi sta sulla chiusura, non su uno dei tre stati.\n     ===================================================================== -->\n<div class="slide lt" id="d08_refyn" data-kind="dossier">\n  <div class="hd"><b>Refyn</b><span class="pg">08 / 19</span></div>\n  <div class="tt tt--sm">Un ciclo che si chiude: priorità, azioni, verifica.</div>\n  <div class="body" style="top:170px">\n    <span class="dev">Modulo avanzato in sviluppo</span>\n  </div>\n\n  <svg class="body" width="1152" height="300" viewBox="0 0 1152 300" style="top:224px"\n       role="img" aria-labelledby="r7t r7d">\n    <title id="r7t">Il ciclo operativo di Refyn</title>\n    <desc id="r7d">Le priorità generano azioni, le azioni vengono verificate contro la\n      baseline e i risultati aggiornano le priorità del ciclo successivo.</desc>\n\n    <!-- CONNETTORE di ritorno: chiude il ciclo, passa sopra i tre stati -->\n    <path d="M1012 74 L1012 20 L140 20 L140 68" fill="none" stroke="#0A0A0A" stroke-width="1.8"/>\n    <polygon points="140,74 134,64 146,64" fill="#0A0A0A"/>\n    <text x="576" y="14" font-family="Geist" font-size="15" fill="rgba(10,10,10,.74)"\n          text-anchor="middle">I risultati aggiornano le priorità del ciclo successivo.</text>\n\n    <!-- i tre stati, stesso trattamento -->\n    <g fill="none" stroke="#0A0A0A" stroke-width="1.5">\n      <rect x="0" y="74" width="280" height="76"/>\n      <rect x="436" y="74" width="280" height="76"/>\n      <rect x="872" y="74" width="280" height="76"/>\n    </g>\n    <g font-family="Geist" font-size="22" font-weight="600" fill="#0A0A0A" text-anchor="middle">\n      <text x="140" y="121">Priorità</text>\n      <text x="576" y="121">Azioni</text>\n      <text x="1012" y="121">Verifica</text>\n    </g>\n\n    <!-- CONNETTORI in avanti -->\n    <path d="M280 112 L424 112" stroke="#0A0A0A" stroke-width="1.5"/>\n    <polygon points="430,112 420,106 420,118" fill="#0A0A0A"/>\n    <path d="M716 112 L860 112" stroke="#0A0A0A" stroke-width="1.5"/>\n    <polygon points="866,112 856,106 856,118" fill="#0A0A0A"/>\n\n    <!-- il contenuto di ogni stato -->\n    <g font-family="Geist" font-size="16" fill="rgba(10,10,10,.74)">\n      <text x="0" y="200">Impatto potenziale</text>\n      <text x="0" y="228">Energia potenzialmente evitabile</text>\n      <text x="0" y="256">Impatto economico stimato</text>\n\n      <text x="436" y="200">Responsabile e ambito</text>\n      <text x="436" y="228">Baseline e target</text>\n      <text x="436" y="256">Scadenza e stato</text>\n\n      <text x="872" y="200">Beneficio verificato</text>\n      <text x="872" y="228">Confronto con la baseline</text>\n      <text x="872" y="256">Periodo di osservazione</text>\n    </g>\n    <!-- SEPARATORI sotto ogni stato -->\n    <g stroke="rgba(10,10,10,.13)" stroke-width="1">\n      <path d="M0 168 L280 168"/><path d="M436 168 L716 168"/><path d="M872 168 L1152 168"/>\n    </g>\n  </svg>\n\n  <div class="body" style="top:556px">\n    <div class="hr"></div>\n    <div class="bd" style="padding-top:16px;max-width:900px">Se il beneficio non è confermato,\n      l’azione viene riesaminata usando i dati del periodo osservato e una baseline aggiornata.</div>\n  </div>\n\n  <div class="ft"><span class="wm">D<i>.</i>Factory</span>\n    <span>Rappresentazione del funzionamento previsto</span></div>\n</div>'
